import{d as c,C as t,o as u,c as b,j as a,a as o,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第十七章","description":"从四等治理、信不足与贵言，读到百姓皆谓我自然。","frontmatter":{"title":"道德经第十七章","description":"从四等治理、信不足与贵言，读到百姓皆谓我自然。","category":"guide","aliases":["道德经第十七章","老子第十七章","dao de jing chapter 17"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-17.md","filePath":"daoism/dao-de-jing/chapter-17.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-17.md"},y=c({...p,setup(g){const n=[{id:"four-forms-of-governing",label:"太上，下知有之",showLabel:!0,sentences:[[{text:"太上",glossary:"taishang"},"，下知有之；"],["其次，亲而",{text:"誉",glossary:"yu"},"之；其次，畏之；其次，",{text:"侮",glossary:"wu"},"之。"]],note:["【白话】最高一等的治理者，下面的人只知道有他；其次，人们亲近而称赞他；再其次，人们畏惧他；更次，人们轻慢他。","【王弼注择要】「太上，谓大人也。」注以「居无为之事，行不言之教」说明只知有之；对畏之则说「赖威权也」。关注点从治理者如何显名，转到百姓怎样生活与回应。","【读法】四等构成评价次序，不是每个政体都会自动经历的历史阶段。下知有之仍承认治理者的存在，不能据此把失职、信息不明也称作最高治理。"]},{id:"trust-begins-above",label:"信不足焉，有不信焉",showLabel:!0,sentences:[[{text:"信",glossary:"xin"},"不足焉，有不信焉。"]],note:["【白话】在上者的诚信不足，就会发生人们不信任的情形。治理中出现不信，须回看自己是否有足够可信的言行。","【王弼注择要】「言从上也。」「己处不足，非智之所济也。」注将不信的原因反求于上，不把智巧手段当作弥补失信的根本办法。","【读法】本页据来源将旧页有不足焉校正为信不足焉。信兼涉诚信与可信，不能只要求别人相信，而不检查承诺、行动和实际结果。"]},{id:"taking-words-seriously",label:"悠兮其贵言",showLabel:!0,sentences:[[{text:"悠",glossary:"you"},"兮其",{text:"贵",glossary:"gui"},"言。"]],note:["【白话】悠然深远啊，他如此珍重自己的言语，不轻易发出承诺与号令。","【王弼注择要】「无物可以易其言，言必有应。」贵言在注中联系言有所应，不是只要话少，便自然高明。","【读法】悠写从容深远、意向不轻露的样子，不等于拖延；贵言要求慎言而能应，不是回避应有的解释、告知与沟通。"]},{id:"people-say-we-did-it-naturally",label:"百姓皆谓我自然",showLabel:!0,sentences:[["功成事",{text:"遂",glossary:"sui"},"，百姓皆谓我",{text:"自然",glossary:"ziran"},"。"]],note:["【白话】功业完成、事情办成，百姓都说：我们自己本来就是这样、是自然而然成就的。","【王弼注择要】「不以形立物。」注又说「百姓不知其所以然也」。治理没有处处把自己的塑造与功劳显在前面，百姓因而不觉时时受人驱使。","【读法】我在这里是百姓的自称，不是治理者自称。自然取自己如此、本然成就之义，不专指山川草木，也不等于没有人付出支持与劳动。"]}],s=[{id:"taishang",term:"太上",sense:1},{id:"yu",term:"誉",sense:1},{id:"wu",term:"侮",sense:1},{id:"xin",term:"信",sense:1},{id:"you",term:"悠",sense:1},{id:"gui",term:"贵",sense:1,context:"贵言指珍重言语，慎发承诺，并使言有所应。"},{id:"sui",term:"遂",sense:1},{id:"ziran",term:"自然",sense:1,context:"我为百姓自称；自己如此、自然而成，不专指自然环境。"}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十七章",tabindex:"-1"},[o("道德经第十七章 "),a("a",{class:"header-anchor",href:"#道德经第十七章","aria-label":'Permalink to "道德经第十七章"'},"​")],-1)),r(i,{title:"事情办成之后，人们觉得是谁的功劳？",summary:"本章先列人们对治理者的四种回应，再反问诚信是否充足、言语是否可应，最后落在百姓的我自然。低显的治理与真实的成事，需要放在一起理解。",points:[{label:"先读",text:"知有、亲誉、畏惧与轻侮怎样构成次序？"},{label:"再辨",text:"不信为何要先从在上者反省？"},{label:"后想",text:"不显功与不承担，各有什么实际表现？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:n,glossary:s,tone:"ink",density:"comfortable","aria-label":"《道德经》第十七章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"太上，下知有之。",tone:"不显而成事",guide:"百姓只知有治理者，不表示治理什么也没做。篇末功成事遂提醒，评价最终仍落在事情是否得以成就。"},{text:"信不足焉，有不信焉。",tone:"反求于上",guide:"把不信只归咎于百姓，便跳过了前半句。王弼明确说言从上也，要求先检查在上者如何安顿自己的言行。"},{text:"百姓皆谓我自然。",tone:"还其自成",guide:"我属于百姓的口吻。成事不被讲成领导者单方面塑造一切，也不需要百姓不断感念其恩。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
